Future<QuoteOverviewResponse> fetchQuoteOverviewData({
  required final String symbol,
  required final List<String> sections,
}) async {
  if (symbol.isEmpty || sections.isEmpty) return QuoteOverviewResponse();

  String url = "${MoGetQuoteApi.quoteOverview}?symbol=${symbol.mapToSymbol()}";
  for (final String section in sections) {
    url += "&sections=$section";
  }

  return await apiCall(
    url: url,
    apiVersion: Constants.API_V4_0,
    runtimeType: QuoteOverviewResponse(),
  );
}

