// chart_prewarm_service.dart
static DateTime? _lastEnsure;
static Future<void> ensureWarm({required String reason}) async {
  final ChartController? c = ChartController.instanceOrNull;
  if (c != null && c.hasMountedScreen) return; // a chart owns the WebView right now
  final DateTime t = now();
  if (_lastEnsure != null && t.difference(_lastEnsure!) < const Duration(minutes: 1)) return;
  _lastEnsure = t;
  try {
    final Map<String, Object?> r = await prewarmCall(); // idempotent; recreates if reclaimed
    AppHiveLogger.log('INFO', _logTag, 'ensureWarm $reason created=${r['created']}');
  } catch (e) {
    AppHiveLogger.log('WARN', _logTag, 'ensureWarm $reason failed: $e');
  }
}

