// chart_controller.dart
Future<void> preloadPage({required Size viewport}) async {
  if (!pagePreloadEnabled() || hasMountedScreen || _currentState != ChartState.initial) return;
  _beginPageLoad('preload');
  final int attempt = loadAttempt;
  final String url = await getChartCompleteUrl();
  await IosWebViewPlugin.prewarm(url: url, javascriptChannels: <String>['ChartAppDelegate'],
      width: viewport.width.round(), height: viewport.height.round()); // real viewport, not 0x0
  _armAckTimer(attempt);
}

